        right: '40px',
        width: '350px',
        background: 'white',
        borderRadius: '24px',
        padding: '32px',
        boxShadow: '0 16px 48px rgba(0,0,0,0.2)',
        zIndex: 1001,
        animation: 'slideIn 0.3s ease'
      }}>
        {isListening ? (
          <>
            <div style={{ textAlign: 'center' }}>
              <div style={{ 
                width: '100px', 
                height: '100px', 
                background: 'linear-gradient(135deg, var(--tech-blue), var(--mint-green))',
                borderRadius: '50%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                margin: '0 auto 20px',
                animation: 'breathe 1s ease-in-out infinite'
              }}>
                <span style={{ fontSize: '48px' }}>🎤</span>
              </div>
              <p style={{ fontSize: '20px', color: 'var(--tech-blue)', fontWeight: '600' }}>
                正在听您说话...
              </p>
            </div>
          </>
        ) : recognizedText ? (
          <>
            <h4 style={{ fontSize: '20px', fontWeight: 'bold', marginBottom: '16px', color: 'var(--tech-blue)' }}>
              您说的是：
            </h4>
            <p style={{ fontSize: '18px', marginBottom: '20px' }}>{recognizedText}</p>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setShowVoicePanel(false)}>
                取消
              </button>
              <button className="btn btn-primary" style={{ flex: 1 }} onClick={() => setShowVoicePanel(false)}>
                确认
              </button>
            </div>
          </>
        ) : (
          <>
            <h4 style={{ fontSize: '20px', fontWeight: 'bold', marginBottom: '16px' }}>
              🎤 语音助手
            </h4>
            <p style={{ fontSize: '16px', color: 'var(--text-light)' }}>
              点击麦克风开始说话
            </p>
            <button className="btn btn-primary" style={{ width: '100%', marginTop: '16px' }} onClick={startVoiceRecognition}>
              开始说话
            </button>
          </>
        )}
      </div>
    );
  };

  if (!isLoggedIn) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="watermark-bg">
      <div className="app-container">
        <header className="header">
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: '20px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '24px' }}>
              <div style={{ fontSize: '64px' }}>🏠</div>
              <div>
                <h1 style={{ fontSize: '42px', marginBottom: '8px' }}>AI 药管家</h1>
                <p style={{ fontSize: '20px' }}>您身边贴心的用药安全小助手</p>
              </div>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
              <div style={{ fontSize: '100px' }}>👨‍⚕️</div>
              <div style={{ textAlign: 'right' }}>
                <p style={{ fontSize: '20px', marginBottom: '8px' }}>
                  您好，{user?.realName || user?.username || '用户'}！
                </p>
                <button 
                  onClick={handleLogout}
                  style={{
                    padding: '12px 24px',
                    fontSize: '16px',
                    background: 'rgba(255,255,255,0.2)',
                    color: 'white',
                    border: '2px solid white',
                    borderRadius: '12px',
                    cursor: 'pointer',
                    transition: 'all 0.3s ease'
                  }}
                >
                  退出登录
                </button>
              </div>
            </div>
          </div>
        </header>

        <div className="main-content">
          <div className="nav-tabs">
            <button className={`nav-tab ${activeTab === 'home' ? 'active' : ''}`} onClick={() => setActiveTab('home')}>
              🏠 首页
            </button>
            <button className={`nav-tab ${activeTab === 'upload' ? 'active' : ''}`} onClick={() => setActiveTab('upload')}>
              📷 识别药品
            </button>
            <button className={`nav-tab ${activeTab === 'explanation' ? 'active' : ''}`} onClick={() => setActiveTab('explanation')}>
              📖 用药说明
            </button>
            <button className={`nav-tab ${activeTab === 'conflict' ? 'active' : ''}`} onClick={() => setActiveTab('conflict')}>
              ⚠️ 冲突检测
            </button>
            <button className={`nav-tab ${activeTab === 'calendar' ? 'active' : ''}`} onClick={() => setActiveTab('calendar')}>
              📅 用药日历
            </button>
            <button className={`nav-tab ${activeTab === 'drugs' ? 'active' : ''}`} onClick={() => setActiveTab('drugs')}>
              🏠 药箱管理
            </button>
            <button className={`nav-tab ${activeTab === 'emergency' ? 'active' : ''}`} onClick={() => setActiveTab('emergency')}>
              🚨 紧急助手
            </button>
          </div>

          {activeTab === 'home' && renderHomeTab()}
          {activeTab === 'upload' && renderUploadTab()}
          {activeTab === 'recognition' && renderRecognitionTab()}
          {activeTab === 'explanation' && renderExplanationTab()}
          {activeTab === 'conflict' && renderConflictTab()}
          {activeTab === 'calendar' && renderCalendarTab()}
          {activeTab === 'drugs' && renderDrugsTab()}
          {activeTab === 'emergency' && renderEmergencyTab()}
        </div>

        {renderVoiceAssistant()}
        {renderVoicePanel()}
      </div>

      {showProfileModal && (
        <ProfileModal 
          onComplete={handleProfileComplete} 
          onClose={() => setShowProfileModal(false)}
        />
      )}
    </div>
  );
}

export default App;
